const incoming = $input.first().json;
const headerKey = incoming.headers?.['idempotency-key'];
const jobId = incoming.body?.job_id;
const scenario = incoming.body?.scenario ?? 'review';

if (!['review', 'clean', 'deterministic_exception'].includes(scenario)) {
  throw new Error('scenario must be review, clean, or deterministic_exception.');
}

const idempotencyKey = headerKey ?? (jobId ? `n8n-phase3:${jobId}` : `n8n-phase3:synthetic-${scenario}-v1`);
if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/.test(idempotencyKey)) {
  throw new Error('The Idempotency-Key or job_id contains unsupported characters or is too long.');
}

const scenarios = {
  review: {
    source: 'n8n-phase3-review',
    appointments: [
      { appointment_id: 'APT-AUTO-001', patient_id: 'PAT-AUTO-001', provider_id: 'PROV-AUTO-01', appointment_date: '2026-08-01', appointment_time: '09:00', service_type: 'Therapy Follow-up', appointment_status: 'Completed' },
      { appointment_id: 'APT-AUTO-002', patient_id: 'PAT-AUTO-002', provider_id: 'PROV-AUTO-01', appointment_date: '2026-08-01', appointment_time: '10:00', service_type: 'Medication Management', appointment_status: 'Completed' },
      { appointment_id: 'APT-AUTO-003', patient_id: 'PAT-AUTO-003', provider_id: 'PROV-AUTO-02', appointment_date: '2026-08-02', appointment_time: '11:00', service_type: 'Initial Assessment', appointment_status: 'Completed' },
      { appointment_id: 'APT-AUTO-004', patient_id: 'PAT-AUTO-004', provider_id: 'PROV-AUTO-02', appointment_date: '2026-08-02', appointment_time: '13:00', service_type: 'Therapy Follow-up', appointment_status: 'Cancelled' }
    ],
    documentation: [
      { note_id: 'NOTE-AUTO-001', appointment_id: 'APT-AUTO-001', patient_id: 'PAT-AUTO-001', provider_id: 'PROV-AUTO-01', note_date: '2026-08-01', note_status: 'Signed', note_type: 'Progress Note', signed_date: '2026-08-01' },
      { note_id: 'NOTE-AUTO-003', appointment_id: 'APT-AUTO-003', patient_id: 'PAT-AUTO-003', provider_id: 'PROV-AUTO-99', note_date: '2026-08-02', note_status: 'Signed', note_type: 'Assessment Note', signed_date: '2026-08-02' }
    ]
  },
  clean: {
    source: 'n8n-phase3-clean',
    appointments: [
      { appointment_id: 'APT-AUTO-CLEAN-001', patient_id: 'PAT-AUTO-CLEAN-001', provider_id: 'PROV-AUTO-01', appointment_date: '2026-08-03', appointment_time: '09:00', service_type: 'Therapy Follow-up', appointment_status: 'Completed' }
    ],
    documentation: [
      { note_id: 'NOTE-AUTO-CLEAN-001', appointment_id: 'APT-AUTO-CLEAN-001', patient_id: 'PAT-AUTO-CLEAN-001', provider_id: 'PROV-AUTO-01', note_date: '2026-08-03', note_status: 'Signed', note_type: 'Progress Note', signed_date: '2026-08-03' }
    ]
  },
  deterministic_exception: {
    source: 'n8n-phase3-deterministic-exception',
    appointments: [
      { appointment_id: 'APT-AUTO-MISSING-001', patient_id: 'PAT-AUTO-MISSING-001', provider_id: 'PROV-AUTO-02', appointment_date: '2026-08-04', appointment_time: '10:00', service_type: 'Medication Management', appointment_status: 'Completed' }
    ],
    documentation: []
  }
};

return [{ json: { api_base_url: 'http://127.0.0.1:8000', idempotency_key: idempotencyKey, scenario, validation_request: scenarios[scenario] } }];

const response = $input.first().json;
const prepared = $('Prepare Synthetic Request').first().json;
const run = response.body;

if (!run?.run_id) {
  throw new Error('The API response did not contain a run_id.');
}

return [{ json: { api_base_url: prepared.api_base_url, idempotency_key: prepared.idempotency_key, create_status_code: response.statusCode, idempotency_replayed: String(response.headers?.['idempotency-replayed']).toLowerCase() === 'true', ...run } }];

const run = $('Store Run Context').first().json;
const response = $input.first().json;

return [{ json: { ...run, results_total: response.total, results: response.items ?? [] } }];

const context = $('Store Results Context').first().json;
const response = $input.first().json;
const exceptions = response.items ?? [];

return [{ json: { ...context, exceptions_total: response.total, exceptions, review_items: exceptions.filter(item => item.requires_review === true) } }];

const data = $input.first().json;
const reviewCases = data.review_items.map(item => ({ record_type: item.record_type, appointment_id: item.appointment_id, provider_id: item.provider_id, rule_code: item.rule_code, issue_codes: item.issue_codes, reason: item.reason }));

return [{ json: { operational_status: 'AWAITING_HUMAN_REVIEW', run_id: data.run_id, idempotency_key: data.idempotency_key, idempotency_replayed: data.idempotency_replayed, create_status_code: data.create_status_code, counts: { appointments: data.appointment_count, documentation: data.documentation_count, results: data.results_total, exceptions: data.exceptions_total, human_review_cases: reviewCases.length }, notification: { channel: 'n8n_execution_output', message: `Run ${data.run_id} has ${reviewCases.length} case(s) requiring human review. Open this execution and inspect review_cases.` }, review_cases: reviewCases, non_review_exception_count: data.exceptions_total - reviewCases.length, deterministic_results_unchanged: true } }];

const failure = $input.first().json;
const raw = failure.error?.message ?? failure.error ?? failure.message;
const errorMessage = typeof raw === 'string' ? raw : 'HTTP request failed after retry attempts.';
return [{ json: { operational_status: 'FAILED', failed_step: 'create_run', run_id: null, idempotency_key: $('Prepare Synthetic Request').first().json.idempotency_key, error_message: errorMessage } }];

const failure = $input.first().json;
const raw = failure.error?.message ?? failure.error ?? failure.message;
const errorMessage = typeof raw === 'string' ? raw : 'HTTP request failed after retry attempts.';
return [{ json: { operational_status: 'FAILED', failed_step: 'fetch_results', run_id: $('Store Run Context').first().json.run_id, idempotency_key: $('Store Run Context').first().json.idempotency_key, error_message: errorMessage } }];

const failure = $input.first().json;
const raw = failure.error?.message ?? failure.error ?? failure.message;
const errorMessage = typeof raw === 'string' ? raw : 'HTTP request failed after retry attempts.';
return [{ json: { operational_status: 'FAILED', failed_step: 'fetch_exceptions', run_id: $('Store Results Context').first().json.run_id, idempotency_key: $('Store Results Context').first().json.idempotency_key, error_message: errorMessage } }];
